+function Protect-Text {
+    param([string]$Text)
+    [regex]::Replace($Text, '(?i)((?:api[_-]?key|authorization|access[_-]?token)\s*[=:]\s*["'']?)[A-Za-z0-9_./+\-=]{20,}', '$1[REDACTED:api-key]')
+}
+$result = switch ($Mode) {
+    'Digest' {
+        $receipts = Get-Content -Raw (Join-Path $root 'hv-ug-r13-audit-Receipts.json') | ConvertFrom-Json
+        $comparisons = Get-Content -Raw (Join-Path $root 'hv-ug-r13-audit-Comparisons.json') | ConvertFrom-Json
+        $pins = Get-Content -Raw (Join-Path $root 'hv-ug-r13-audit-Pins.json') | ConvertFrom-Json
+        [pscustomobject]@{
+            receipts = $receipts.Count
+            receiptProblems = @($receipts | Where-Object { @($_.trx | Where-Object { $_.missing -or -not $_.hashMatches -or $_.actual.total -ne $_.declaredTotal -or $_.actual.nonPassed.Count }).Count } | Select-Object name,exitCode,total,failed,skipped,trx)
+            finalNonDocs = @($receipts | Where-Object name -like 'ug-r13z11-final*' | Select-Object name,nonDocsDirty,trackedDirty)
+            comparisonChanges = @($comparisons | Where-Object { $_.added.Count -or $_.removed.Count } | Select-Object set,group,total,unique,added,removed)
+            pins = @($pins | Select-Object mock,binding,ordered,mockCounts,bindingCounts,missing,@{n='changedPins';e={@($_.compared | Where-Object { -not $_.unchanged }).path}})
+        }
+    }
+    'Transcript' {
+        $source = '/home/sharpninja/.claude/projects/-home-sharpninja-github-McpServer/cea7a82d-3843-4f79-8b4a-4f40d4a21532.jsonl'
+        $lineNumber = 0
+        foreach ($line in [IO.File]::ReadLines($source)) {
+            $lineNumber++
+            try { $entry = $line | ConvertFrom-Json -Depth 100 } catch { continue }
+            if ($entry.type -eq 'user') {
+                $pieces = @(foreach ($part in $entry.message.content) { if ($part -is [string]) { $part } elseif ($part.type -eq 'text') { $part.text } })
+                $body = $pieces -join "`n"
+                if ($body -match $Pattern) { [pscustomobject]@{ line = $lineNumber; timestamp = $entry.timestamp; role = 'user'; text = Protect-Text $body } }
+            }
+            if ($entry.type -eq 'assistant') {
+                foreach ($part in $entry.message.content) {
+                    if ($part.type -eq 'tool_use' -and $part.name -match 'AskUserQuestion' -and ($part.input | ConvertTo-Json -Depth 30) -match $Pattern) { [pscustomobject]@{ line = $lineNumber; timestamp = $entry.timestamp; role = 'question'; input = $part.input } }
+                }
+            }
+        }
+    }
+    'Stores' {
+        foreach ($file in Get-ChildItem -LiteralPath $root -Filter 'hv-ug-r13-store-*.json' -File) {
+            if ($file.Name -notmatch $Pattern) { continue }
+            $record = Get-Content -LiteralPath $file.FullName -Raw | ConvertFrom-Json -Depth 100
+            [pscustomobject]@{ file = $file.Name; data = $record }
+        }
+    }
+    'Closures' {
+        foreach ($file in Get-ChildItem -LiteralPath $root -Filter 'hostile-validator-*.json' -File) {
+            if ($file.Name -notmatch $Pattern) { continue }
+            $record = Get-Content -LiteralPath $file.FullName -Raw | ConvertFrom-Json -Depth 100
+            [pscustomobject]@{ file = $file.Name; keys = @($record.PSObject.Properties.Name); verdict = $record.overallVerdict; accuracy = $record.accuracy; completeness = $record.completeness; failList = $record.failList; findings = $record.findings; closure = $record.closure }
+        }
+    }
+    'Hygiene' {
+        $commits = @(& git --no-optional-locks log --first-parent '--format=%H' '3da2db93..11326d42')
+        $signatures = @(foreach ($commit in $commits) {
+            $message = (& git --no-optional-locks show -s '--format=%B' $commit) -join "`n"
+            [pscustomobject]@{ commit = $commit; signLine = @($message -split "`n" | Where-Object { $_ -match '^Signed:' }); hasGpgSignature = ((& git --no-optional-locks cat-file commit $commit) -match '^gpgsig ').Count -gt 0 }
+        })
+        $docs = @('docs/plans/2026-10-19-unit-suite-green.md','docs/receipts/hv/unitgreen-r13-prelaunch.pr-description.md')
+        $formatHits = @(foreach ($document in $docs) {
+            $number = 0
+            foreach ($line in [IO.File]::ReadLines((Join-Path (Get-Location) $document))) { $number++; if ($line -match '[\u2013\u2014]|^\s*\|.*\|\s*$') { [pscustomobject]@{ path = $document; line = $number; text = $line } } }
+        })
+        $base = (& git --no-optional-locks merge-base '9b099716' '11326d42').Trim()
+        $mergeOutput = @(& git --no-optional-locks merge-tree $base '11326d42' '9b099716')
+        $mergeExit = $LASTEXITCODE
+        [pscustomobject]@{ signatures = $signatures; formatting = $formatHits; mergeBase = $base; mergeTreeExitCode = $mergeExit; mergeTreeOutput = $mergeOutput; scannerHistory = @(& git --no-optional-locks log '--format=%H %aI %s' '3da2db93..11326d42' -- 'tests/QBrainAi.Support.Mcp.Tests/Configuration/UnitSuitePlatformScanner*.cs') }
+    }
+}
+$items = @($result)
+$serialized = Protect-Text ($items | ConvertTo-Json -Depth 100)
+$destination = Join-Path $root ('hv-ug-r13-review-' + $Mode + '-' + $Label + '.json')
+if ($PSCmdlet.ShouldProcess($destination, 'Save read-only review evidence')) { [IO.File]::WriteAllText($destination, $serialized) }
