+# Validate only review artifacts and read-only workspace/session evidence.
+[CmdletBinding(SupportsShouldProcess)]
+param([ValidateSet('Validate','Persistence','TerminalCommands','FinalStatus')][string]$Mode='Validate')
+$ErrorActionPreference='Stop'
+$env:GIT_OPTIONAL_LOCKS='0'
+$root='/home/sharpninja/github/McpServer/.worktrees/unit-suite-green-20261019'
+$hv=Join-Path $root 'docs/receipts/hv'
+$mdPath=Join-Path $hv 'hostile-validator-unitgreen-r13-20261105T234506.md'
