+$prose=[IO.File]::ReadAllText($mdPath)
+$report=Get-Content -LiteralPath $jsonPath -Raw | ConvertFrom-Json -Depth 100
+$data=switch($Mode) {
+    'Validate' {
+        $errors=[Collections.Generic.List[string]]::new()
+        if($report.claims.Count -ne 54){$errors.Add('Claim count')}
+        if($report.closure.Count -ne 42){$errors.Add('Closure count')}
+        foreach($state in @('PASS','FAIL','UNKNOWN')) {
+            $actual=@($report.claims | Where-Object status -EQ $state).Count
+            $property=($state.ToLowerInvariant()+'Count')
+            if($actual -ne $report.$property){$errors.Add('Count mismatch '+$state)}
+        }
+        foreach($claim in $report.claims){if(-not $prose.Contains($claim.id+' - '+$claim.status+'. '+$claim.assessment,[StringComparison]::Ordinal)){$errors.Add('Missing prose '+$claim.id)}}
+        foreach($item in $report.closure){if(-not $prose.Contains($item.id+' - '+$item.status+'. '+$item.evidence,[StringComparison]::Ordinal)){$errors.Add('Missing closure '+$item.id)}}
+        $delimiter='=== VERDICT JSON ==='
+        $last=$prose.LastIndexOf($delimiter,[StringComparison]::Ordinal)
+        if($last -lt 0){$errors.Add('Missing verdict delimiter')}else{
+            $embedded=$prose.Substring($last+$delimiter.Length).Trim() | ConvertFrom-Json -Depth 100
+            if(($embedded | ConvertTo-Json -Depth 100 -Compress) -cne ($report.verdict | ConvertTo-Json -Depth 100 -Compress)){$errors.Add('Embedded verdict differs')}
+        }
+        $keyMatch=[regex]::Match([IO.File]::ReadAllText('/home/sharpninja/github/McpServer/AGENTS-README-FIRST.yaml'),'(?m)^apiKey:\s*(.+)$')
+        $key=$keyMatch.Groups[1].Value.Trim().Trim('"',"'")
+        if($key.Length -ge 20 -and ($prose.Contains($key,[StringComparison]::Ordinal) -or [IO.File]::ReadAllText($jsonPath).Contains($key,[StringComparison]::Ordinal))){$errors.Add('Secret detected; do not publish')}
+        $requestPath=Join-Path $hv '20261105T234506-unitgreen-r13.request.jsonl'
+        $responsePath=Join-Path $hv '20261105T234506-unitgreen-r13.response.jsonl'
+        foreach($path in @($requestPath,$responsePath)){if(-not (Test-Path -LiteralPath $path)){$errors.Add('Missing paired JSONL '+$path)}}
+        [pscustomobject]@{ errors=@($errors); pass=$report.passCount; fail=$report.failCount; unknown=$report.unknownCount; claimCount=$report.claims.Count; closureCount=$report.closure.Count; sourceHead=$report.headSha; proseSha256=(Get-FileHash -LiteralPath $mdPath -Algorithm SHA256).Hash; jsonSha256=(Get-FileHash -LiteralPath $jsonPath -Algorithm SHA256).Hash; proseBytes=(Get-Item -LiteralPath $mdPath).Length; jsonBytes=(Get-Item -LiteralPath $jsonPath).Length; requestBytes=(Get-Item -LiteralPath $requestPath).Length; responseBytesAtInspection=(Get-Item -LiteralPath $responsePath).Length; markerKeyRetained=$false }
+    }
+    'Persistence' {
+        $full=Get-Content -LiteralPath (Join-Path $hv 'hv-ug-r13-store-readown-final.json') -Raw | ConvertFrom-Json -Depth 100
+        $sessions=@($full.response.payload.result.items | Where-Object sessionId -EQ 'Codex-20261106T055000Z-plugin-session')
+        if($sessions.Count -ne 1){throw 'Exact own session not found.'}
+        $turns=@($sessions[0].turns | Where-Object requestId -EQ 'req-20261106T055026Z-unitgreen-r13')
+        if($turns.Count -ne 1){throw 'Exact own turn not found.'}
+        $turn=$turns[0]
+        $retained=[string]$turn.response
+        $hash=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($retained)))
+        $localHash=(Get-FileHash -LiteralPath $mdPath -Algorithm SHA256).Hash
+        if($hash -cne $localHash -or $retained -cne $prose){throw 'Persisted full response differs from complete prose receipt.'}
+        if($turn.status -ne 'completed'){throw ('Turn status is '+$turn.status)}
+        $historyPath=Join-Path $hv 'hv-ug-r13-store-history-final.json'
+        if(-not (Test-Path -LiteralPath $historyPath)){throw 'History query receipt missing.'}
+        [pscustomobject]@{ sessionId=$sessions[0].sessionId; requestId=$turn.requestId; status=$turn.status; sourceType=$sessions[0].sourceType; threadId=$sessions[0].agentSessionId; exactFullResponseMatch=$true; responseCharacters=$retained.Length; persistedResponseSha256=$hash; proseReceiptSha256=$localHash; fullReadbackPath=(Join-Path $hv 'hv-ug-r13-store-readown-final.json'); historyPath=$historyPath; designDecisionCount=@($turn.designDecisions).Count; actionCount=@($turn.actions).Count; dialogCount=@($turn.processingDialog).Count; includesEveryClaim=$true; includesEveryFinding=$true; includesCompleteVerdictJson=$true; includesCommandLedger=$true }
+    }
+    'TerminalCommands' {
+        $inventory=Get-Content -LiteralPath (Join-Path $hv 'hv-ug-r13-crosschecks-CommandInventory.json') -Raw | ConvertFrom-Json -Depth 100
+        $since=[DateTimeOffset]::Parse($report.commandsSnapshotUtc)
+        @($inventory.data | Where-Object { $_.commands.Count -and [DateTimeOffset]::Parse($_.timestamp) -ge $since } | ForEach-Object { [pscustomobject]@{timestampUtc=$_.timestamp;toolCallId=$_.toolCallId;commands=$_.commands;exitCodes=$_.exitCodes;exitCodeStatus=if($_.exitCodes.Count){'Observed'}else{'Not retained'}} })
+    }
+    'FinalStatus' {
+        $currentHead=(& git rev-parse HEAD).Trim(); $headExit=$LASTEXITCODE
+        $tracked=@(& git status --porcelain=v1 --untracked-files=no); $statusExit=$LASTEXITCODE
+        $changePaths=@(& git diff --name-only '53a210ca..11326d42'); $diffExit=$LASTEXITCODE
+        $nonDocs=@($changePaths | Where-Object {-not $_.StartsWith('docs/',[StringComparison]::Ordinal)})
+        if($currentHead -cne $report.headSha -or $tracked.Count -or $nonDocs.Count -or $headExit -ne 0 -or $statusExit -ne 0 -or $diffExit -ne 0){throw 'Final head or tracked-tree invariant failed.'}
+        [pscustomobject]@{head=$currentHead;trackedChanges=$tracked;nonDocsAfterCodeHead=$nonDocs;gitExitCodes=@($headExit,$statusExit,$diffExit);codeBuildTestExecutionByReviewer=0;proseSha256=(Get-FileHash -LiteralPath $mdPath -Algorithm SHA256).Hash;jsonSha256=(Get-FileHash -LiteralPath $jsonPath -Algorithm SHA256).Hash}
+    }
+}
+$destination=if($Mode -eq 'Persistence'){Join-Path $hv 'hv-ug-r13-persistence-proof.json'}else{Join-Path $hv ('hv-ug-r13-verdict-'+$Mode.ToLowerInvariant()+'.json')}
+$result=[pscustomobject][ordered]@{timestampUtc=[DateTimeOffset]::UtcNow.ToString('o');timestampLocal=Get-Date -Format s;mode=$Mode;data=$data}
+if($Mode -eq 'Validate' -and $data.errors.Count){$result | ConvertTo-Json -Depth 30;throw 'Verdict validation found errors.'}
+if($PSCmdlet.ShouldProcess($destination,'Write review verification receipt')){[IO.File]::WriteAllText($destination,($result | ConvertTo-Json -Depth 100))}
+if($Mode -eq 'TerminalCommands'){[pscustomobject]@{timestampLocal=$result.timestampLocal;commandGroups=@($data).Count;destination=$destination} | ConvertTo-Json}else{$result | ConvertTo-Json -Depth 30}
*** End Patch"));
